/**
 * The structural model for the ONE HCL parse/render surface (plan §4.1).
 * Extractors consume TfBlock; toHcl emitters produce TfBlock. A second HCL
 * dialect cannot exist because a second parser/renderer doesn't.
 *
 * Expressions are tagged with `$expr` (not the plan sketch's bare `kind`)
 * so a plain object value from a jsonencode payload can never be mistaken
 * for an expression — payload objects are user data and may contain any key,
 * so parseJsonencodePayload loud-errors on a literal `$expr` key instead.
 */
const EXPR_KINDS = new Set([
    "resource-attr",
    "data-attr",
    "local",
    "variable",
    "jsonencode",
    "template",
    "scoped-attr",
    "for-object",
]);
export function isTfExpr(v) {
    return (typeof v === "object" &&
        v !== null &&
        !Array.isArray(v) &&
        typeof v.$expr === "string" &&
        EXPR_KINDS.has(v.$expr));
}
export const expr = {
    resourceAttr(type, label, path = []) {
        return { $expr: "resource-attr", type, label, path };
    },
    dataAttr(type, label, path = []) {
        return { $expr: "data-attr", type, label, path };
    },
    local(name, path = []) {
        return { $expr: "local", name, path };
    },
    variable(name, path = []) {
        return { $expr: "variable", name, path };
    },
    jsonencode(value) {
        return { $expr: "jsonencode", value };
    },
    template(parts) {
        return { $expr: "template", parts };
    },
    scopedAttr(name, path = []) {
        return { $expr: "scoped-attr", name, path };
    },
    forObject(variable, collection, key, value) {
        return { $expr: "for-object", variable, collection, key, value };
    },
};
